<script module lang="ts">
/**
 * Chooses light, dark or the system's mode (`design/components/mode-switch.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/mode-switch.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, setContext } from 'svelte'

import { agentMember, joinSlot, setMode, useMode, watchEffect } from '@polymorph/svelte'
import SegmentedControl from './SegmentedControl.svelte'

export interface ModeSwitchMessages {
  /** The segment that pins the light mode: "Light". */
  light: string
  /** The segment that pins the dark mode: "Dark". */
  dark: string
  /** The segment that follows the operating system's mode: "System". */
  system: string
}

export interface ModeSwitchProps {
  disabled?: boolean
  /**
   * The group's accessible name ("Appearance"), because outside a form no FormField names it.
   */
  label: string
  /**
   * Omit for the English defaults; a localized application passes every key.
   */
  messages?: ModeSwitchMessages
  /**
   * The reader's choice. Uncontrolled, it is called after the mode is set.
   */
  onChange?: (value: 'light' | 'dark' | 'system') => void
  /**
   * SegmentedControl's sizes: it sits in a toolbar, a menu's header or a settings row.
   */
  size?: 'sm' | 'md'
  /**
   * The choice shown, while the application holds it. With it, a choice calls `onChange` and
   * sets no mode. Without it, the ModeSwitch shows the document's preference and sets the mode.
   */
  value?: 'light' | 'dark' | 'system'
}
</script>

<script lang="ts">
let {
  disabled = false,
  label: labelOwn,
  messages = (() => ({ light: 'Light', dark: 'Dark', system: 'System' }))(),
  onChange,
  size = 'md',
  value,
}: ModeSwitchProps = $props()
const joined = joinSlot(undefined, () => ({ disabled: disabled, label: labelOwn, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
setContext('polymorph:identity', 'mode-switch')
const borrowed: { element?: () => Element | null | undefined } = {}
setContext('polymorph:borrowed', borrowed)
const runtime = useMode()
const options = $derived([
  { value: 'light', label: messages.light, icon: 'mode-light' as const },
  { value: 'dark', label: messages.dark, icon: 'mode-dark' as const },
  { value: 'system', label: messages.system, icon: 'mode-system' as const },
])
const shown = $derived(value ?? runtime.current.preference)
const choose = $derived((next: string): void => {
  const picked = next === 'light' || next === 'dark' ? next : 'system'
  if (value === undefined) setMode(picked)
  onChange?.(picked)
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'ModeSwitch',
    element: () => borrowed.element?.(),
    state: () => ({
      value: shown,
      options: options.map((option) => ({ id: option.value, label: option.label })),
      disabled: disabled,
    }),
    actions: { choose: { argument: 'id', run: (value) => value !== shown && choose(value) } },
    withholds: () => borrowed.element?.(),
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<SegmentedControl
    {options}
    value={shown}
    {label}
    {size}
    {disabled}
    onChange={(event) => { choose(event) }}
/>{/if
}{@render joined.end?.()}
